#include "refinement-geometry.hpp"
#include <algorithm>
#include <cstring>
namespace dome::detail {
namespace {
void stop(const PaintSamplingLimits&l){if(l.cancelled&&l.cancelled())throw std::runtime_error("Refinement geometry cancelled");}
size_t resident(const Mesh&m,size_t cap){size_t bytes=sizeof(Mesh);auto add=[&](size_t n,size_t unit){if(bytes>cap||n>(cap-bytes)/unit)throw std::length_error("Refinement geometry resident capacity exceeds working quota");bytes+=n*unit;};add(m.positions.capacity(),sizeof(Vec3));add(m.normals.capacity(),sizeof(Vec3));add(m.uv.capacity(),sizeof(std::array<float,2>));add(m.indices.capacity(),sizeof(uint32_t));add(m.uv_pins.capacity(),1);add(m.uv_seams.capacity(),1);return bytes;}
KeyMirrorLimits policy(const Mesh&m,const PaintSamplingLimits&l,size_t later){
 if(!l.max_working_bytes||l.max_working_bytes>512*1024*1024||!l.max_work||l.max_work>256'000'000||!l.max_vertices||l.max_vertices>2'000'000||!l.max_triangles||l.max_triangles>2'000'000||!l.max_basis_bytes||l.max_basis_bytes>128*1024*1024)throw std::invalid_argument("Invalid owning refinement geometry policy");
 const size_t overhead=sizeof(RefinementGeometry)+sizeof(Mesh)+128;
 if(l.max_working_bytes<=overhead)throw std::length_error("Refinement geometry snapshot exceeds full working quota");
 const auto source_bytes=resident(m,l.max_working_bytes);if(source_bytes>(l.max_working_bytes-overhead)/2)throw std::length_error("Refinement geometry snapshot exceeds full working quota");const auto before=2*source_bytes+overhead;if(before>=l.max_working_bytes)throw std::length_error("Refinement geometry source exceeds full working quota before kernel allocation");
 if(later>l.max_working_bytes-(2*sizeof(Vec3)+sizeof(std::array<float,2>)+sizeof(uint32_t)))throw std::length_error("Refinement geometry later endpoint reservation exceeds working quota");
 KeyMirrorLimits p;p.cancelled=l.cancelled;p.max_work=size_t(l.max_work);p.max_bytes=std::min(size_t(256*1024*1024),l.max_working_bytes-before);p.reserved_output_corner_bytes=2*sizeof(Vec3)+sizeof(std::array<float,2>)+sizeof(uint32_t)+(m.uv_pins.empty()?0:1)+(m.uv_seams.empty()?0:1)+later;return p;
}
Mesh make_mesh(const KeyMirrorRefinement&r,const std::function<bool()> &cancelled){Mesh out;const auto n=r.corners.size();out.positions.reserve(n);out.normals.reserve(n);out.uv.reserve(n);out.indices.reserve(n);if(!r.source->uv_pins.empty())out.uv_pins.resize(n);if(!r.source->uv_seams.empty())out.uv_seams.resize(n);for(const auto &c:r.corners){if((out.indices.size()&1023)==0&&cancelled&&cancelled())throw std::runtime_error("Refinement geometry mesh build cancelled");Vec3 normal{};std::array<float,2>uv{};for(size_t k=0;k<3;++k){const auto v=r.source->indices.at(c.current.triangle*3+k);normal+=r.source->normals[v]*float(c.current.barycentric[k]);for(size_t d=0;d<2;++d)uv[d]+=r.source->uv[v][d]*float(c.current.barycentric[k]);}out.positions.push_back(c.position);out.normals.push_back(normal);out.uv.push_back(uv);out.indices.push_back(uint32_t(out.indices.size()));}out.validate();return out;}
template<class T>bool same(const std::vector<T>&a,const std::vector<T>&b){return a.size()==b.size()&&(a.empty()||!std::memcmp(a.data(),b.data(),a.size()*sizeof(T)));}
bool equal(const KeyMirrorRefinement&a,const KeyMirrorRefinement&b){if(a.source!=b.source||a.source.owner_before(b.source)||b.source.owner_before(a.source)||a.plane_offset!=b.plane_offset||a.opposite!=b.opposite||a.corners.size()!=b.corners.size())return false;for(size_t i=0;i<a.corners.size();++i){const auto &x=a.corners[i],&y=b.corners[i];if(x.current.triangle!=y.current.triangle||x.reflected.triangle!=y.reflected.triangle||x.current.barycentric!=y.current.barycentric||x.reflected.barycentric!=y.reflected.barycentric||std::memcmp(&x.position,&y.position,sizeof(Vec3)))return false;}return true;}
}
bool RefinementGeometry::valid_owner(const std::shared_ptr<const RefinementGeometry>&p)const noexcept{return p.get()==this&&!self_.expired()&&!self_.owner_before(p)&&!p.owner_before(self_);}
bool RefinementGeometry::matches_source(const std::shared_ptr<const Mesh>&source)const noexcept{
 const auto own=source_owner_.lock();if(!source||!own||source!=own||source.owner_before(own)||own.owner_before(source))return false;const auto &a=*source,&b=*refinement_.source;return same(a.positions,b.positions)&&same(a.normals,b.normals)&&a.uv==b.uv&&a.indices==b.indices&&a.uv_pins==b.uv_pins&&a.uv_seams==b.uv_seams;
}
size_t RefinementGeometry::retained_bytes()const{return sizeof(RefinementGeometry)+resident(*source(),512*1024*1024)+resident(*mesh_,512*1024*1024)+refinement_.corners.capacity()*sizeof(MirrorRefinementCorner)+refinement_.opposite.capacity()*sizeof(uint32_t);}
std::shared_ptr<const RefinementGeometry> RefinementGeometry::create(std::shared_ptr<const Mesh> source,KeyMirrorPlane plane,float tolerance,const PaintSamplingLimits&l,size_t later){
 stop(l);if(!source)throw std::invalid_argument("Refinement geometry requires actual immutable source");
 if(std::any_of(source->uv_pins.begin(),source->uv_pins.end(),[](auto v){return v!=0;})||std::any_of(source->uv_seams.begin(),source->uv_seams.end(),[](auto v){return v!=0;}))throw std::invalid_argument("Refinement geometry needs genuine pin/edge transport for nonempty controls");
 const auto p=policy(*source,l,later);auto snapshot=std::make_shared<const Mesh>(*source);auto r=refine_reflected_key(snapshot,plane,tolerance,p);if(r.corners.size()>l.max_vertices||r.corners.size()/3>l.max_triangles)throw std::length_error("Refinement geometry output exceeds declared dimensions before mesh allocation");
 const size_t own=sizeof(Mesh)+r.corners.size()*(2*sizeof(Vec3)+sizeof(std::array<float,2>)+sizeof(uint32_t)+(source->uv_pins.empty()?0:1)+(source->uv_seams.empty()?0:1))+r.corners.capacity()*sizeof(MirrorRefinementCorner)+r.opposite.capacity()*sizeof(uint32_t);
 const size_t required=2*resident(*source,l.max_working_bytes)+sizeof(RefinementGeometry)+sizeof(Mesh)+128+r.working_bytes+own;if(required>l.max_working_bytes)throw std::length_error("Refinement geometry complete capture/replay quota exceeded before mesh allocation");
 auto owner=std::shared_ptr<RefinementGeometry>(new RefinementGeometry);owner->self_=owner;owner->source_owner_=source;owner->tolerance_=tolerance;owner->later_bytes_per_corner_=later;owner->working_bytes_=required;owner->refinement_=std::move(r);owner->mesh_=std::make_shared<const Mesh>(make_mesh(owner->refinement_,l.cancelled));stop(l);return owner;
}
void RefinementGeometry::validate(const PaintSamplingLimits&l)const{
 stop(l);if(!valid_owner(self_.lock())||!mesh_||!refinement_.source)throw std::invalid_argument("Refinement geometry lost its actual owning lease");const size_t own=resident(*mesh_,l.max_working_bytes)+refinement_.corners.capacity()*sizeof(MirrorRefinementCorner)+refinement_.opposite.capacity()*sizeof(uint32_t);if(own>=l.max_working_bytes)throw std::length_error("Refinement geometry resident replay context exceeds working quota");auto replay_limits=l;replay_limits.max_working_bytes-=own;const auto p=policy(*source(),replay_limits,later_bytes_per_corner_);if(working_bytes_>l.max_working_bytes||mesh_->positions.size()>l.max_vertices||mesh_->indices.size()/3>l.max_triangles)throw std::length_error("Refinement geometry exceeds caller resource context before replay");auto replay=refine_reflected_key(source(),KeyMirrorPlane{refinement_.plane_offset},tolerance_,p);if(!equal(replay,refinement_))throw std::invalid_argument("Refinement geometry stencil differs from complete source replay");const auto expected=make_mesh(replay,l.cancelled);if(!same(expected.positions,mesh_->positions)||!same(expected.normals,mesh_->normals)||expected.uv!=mesh_->uv||expected.indices!=mesh_->indices||expected.uv_pins!=mesh_->uv_pins||expected.uv_seams!=mesh_->uv_seams)throw std::invalid_argument("Refinement geometry current mesh differs from actual replay");stop(l);
}
}
